INSERT INTO "public"."chat_message" VALUES ('2032729685755797506', '2032729674896744449', 2, 'f', '电影《只此青绿》以宋代名画《千里江山图》为灵感，通过舞蹈与影像融合，展现中国传统美学的诗意与意境。', 'ASSISTANT', '[]', 'f', '2026-03-14 16:04:58.045002', '2026-03-14 16:04:58.045002', 'f', NULL, NULL);
INSERT INTO "public"."chat_message" VALUES ('2032729997904289794', '2032729995110883329', 1, 'f', '只此青绿是什么？', 'USER', '[]', 'f', '2026-03-14 16:06:12.462739', '2026-03-14 16:06:12.462739', 'f', NULL, NULL);
INSERT INTO "public"."chat_message" VALUES ('2032730016971595778', '2032729995110883329', 2, 'f', '《只此青绿》是一部以北宋画家王希孟的传世名作《千里江山图》为灵感创作的舞蹈诗剧，由中国东方演艺集团出品。作品通过舞蹈、音乐与舞美设计，展现中国传统美学意境，讲述一位现代研究员与画作跨越时空的对话，呈现青绿色彩所象征的东方山水精神。该剧自2021年首演以来广受好评，并登上2022年央视春晚舞台。', 'ASSISTANT', '[]', 'f', '2026-03-14 16:06:17.013038', '2026-03-14 16:06:17.013038', 'f', NULL, NULL);
INSERT INTO "public"."chat_message" VALUES ('2032730291618816002', '2032730281275662338', 1, 'f', '只此青绿', 'USER', '[]', 'f', '2026-03-14 16:07:22.482878', '2026-03-14 16:07:22.482878', 'f', NULL, NULL);
