INSERT INTO "public"."chat_message" VALUES ('2034472582679134209', '2034472483655811073', 2, 'f', '题目：个人知识库驱动的 AI 自我认知系统  
学院：计算机科学与工程学院  
专业：软件工程  
学生姓名：王泰乐  
学号：20221914  
校内指导教师：周涛  

选题目的与意义：构建面向个体用户的个人知识库系统，整合结构化与非结构化数据，实现对个人知识、经历和兴趣活动的系统化存储、智能化组织与高效检索，打造“第二大脑”，应对信息碎片化问题。结合人工智能与自然语言处理技术，支持多模态内容（文本、图片、视频）管理与自然语言检索，提升个人知识管理能力与信息利用效率。

基本内容：基于 Spring Boot3.x + Vue3.x 开发个人知识库管理系统，采用前后端分离架构。后端使用 Spring Boot3.x，前端使用 Vue3.x 构建 SPA；数据层采用 MySQL 存储结构化元数据，MongoDB 存储非结构化内容描述，Redis 缓存热点数据，MinIO 存储多模态文件。核心功能包括多模态内容管理、自然语言检索、用户认证与权限控制、多终端适配界面。

开发流程：需求分析 → 系统设计 → 分模块实现 → 集成测试 → 优化完善。使用 UML 工具完成类图、用例图等设计。

进度规划：  
- 2025.11.09–2025.11.24：下达任务书、提交开题报告  
- 2025.11.25–2025.12.10：资料查阅、研究现状分析、可行性研究  
- 2025.12.11–2025.12.25：需求分析与总体设计  
- 2025.12.26–2026.01.20：后端核心功能开发  
- 2026.01.21–2026.02.15：前端界面实现与联调  
- 2026.02.16–2026.03.01：系统联调、测试与优化  
- 2026.03.01–2026.04.06：撰写论文、中期检查  
- 后续阶段包括论文检测、评阅、答辩等，至 2026.05.26 结束。

重点研究内容：  
1. 多模态个人知识库建模与管理  
2. 基于自然语言的智能检索  
3. 系统性能与响应优化  
4. 多终端适配与交互设计

参考文献包括程宏达（2013）、刘子凡与郭昱君（2021）、李亚芳（2010）、赵东伟（2009）、赵静静等（2022）、殷佳庭与陆婷婷（2024）、罗涛（2020）、冯岩（2018）等关于个人知识管理、Spring Boot 应用及 MinIO 存储的研究。', 'ASSISTANT', '[]', 'f', '2026-03-19 11:30:37.053384', '2026-03-19 11:30:37.053384', 'f', NULL, NULL);
