COMMENT ON COLUMN "public"."content"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."content"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."content"."deleted" IS '是否删除';
COMMENT ON COLUMN "public"."content"."creator" IS '创建人';
