INSERT INTO "public"."content" VALUES ('0b43c49c4a9c451654080418c280389b', '只此青绿', '电影《只此青绿》以宋代名画《千里江山图》为灵感，通过舞蹈与影像融合，展现中国传统美学与文化意境。', 'article', 'content-covers/cover_42341e0e-0921-4316-b093-368d5d02ad76.png', '电影', 0, 5, 't', '2026-03-12 13:52:28.76378', '2026-03-19 10:20:20.290305', 'f', NULL, NULL, NULL, NULL, NULL, 'article');
INSERT INTO "public"."content" VALUES ('546a9d097212881ec0b0bfd453a68285', '第二十三届田径运动会', '第二十三届田径运动会顺利举行，展现了运动员们的拼搏精神与竞技风采。', 'study', 'default/content/cover_f72beea0-db27-4d6b-a6bb-a016fbdd2b38.jpg', '# 第二十三届田径运动会', 0, 1, 'f', '2026-05-06 14:19:16.906083', '2026-05-06 14:20:06.677351', 'f', NULL, NULL, 'file', '', 0, 'article');
INSERT INTO "public"."content" VALUES ('3a37eeadb28a7c416d7f5ea4dca81f4b', '脱脂牛马', '“脱脂牛马”以轻松幽默的笔调，讲述陪伴与疯狂同行的青春故事，传递出真挚友情与无畏生活的态度。', 'article', 'content-covers/cover_f60df320-e831-4b45-a3da-1f797f584bf2.png', '我陪你去疯！', 0, 2, 'f', '2026-03-12 14:03:04.944135', '2026-03-19 09:18:21.932261', 'f', NULL, NULL, NULL, NULL, NULL, 'article');
INSERT INTO "public"."content" VALUES ('4f406c1c00164c32d25ff6d4c3f890d8', '自由', '文章探讨了自由的内涵，强调自由不仅是权利，更需责任与边界，呼吁在尊重他人和社会规则的前提下实现真正的自由。', 'article', 'content-covers/cover_099108d0-7daf-424e-bb3c-b63dc1f8f91e.png', '', 0, 0, 'f', '2026-04-07 16:55:30.305321', '2026-04-07 23:05:32.198243', 't', NULL, NULL, 'link', 'https://v.douyin.com/JlQUNlYg0SA/', 0, 'video');
INSERT INTO "public"."content" VALUES ('ac3300c4320e52edda4cc08a2c6ac4d2', '自由', '文章探讨了自由的内涵，强调其不仅是外在权利，更是内心的独立与选择能力。', 'article', 'content-covers/cover_d5ce5b68-96a9-4631-a457-a9bd452ee78b.png', '', 0, 2, 'f', '2026-04-07 16:57:23.656486', '2026-04-07 23:05:36.073154', 't', NULL, NULL, 'link', 'https://v.douyin.com/JlQUNlYg0SA/', 0, 'video');
INSERT INTO "public"."content" VALUES ('eda15101cef6f4530ace6dd23970ec99', '青岛', '青岛是一座美丽的海滨城市，以其红瓦绿树、碧海蓝天和独特的德式建筑闻名，同时是重要的港口和旅游胜地。', 'article', 'default/content/cover_60441ea6-c972-4ac7-ba85-7ea12c16105a.jpg', '', 2, 30, 't', '2026-03-17 20:04:52.01194', '2026-05-06 14:17:05.366604', 'f', NULL, NULL, 'link', 'https://www.bilibili.com/video/BV1moSUBGE9u?t=3.4', 0, 'video');
INSERT INTO "public"."content" VALUES ('8af254eae2d15e5815dfae35c6990846', '人生是旷野，不是轨道', '人生如旷野，充满无限可能，而非被限定在既定轨道上。', 'article', 'default/content/cover_ecd66886-5b6d-416a-ac37-78a3b02ee927.jpg', '# Cool', 0, 3, 't', '2026-03-12 13:37:02.454011', '2026-03-14 11:12:16.073496', 'f', NULL, NULL, NULL, NULL, NULL, 'article');
INSERT INTO "public"."content" VALUES ('18eb9d52d84827b2cd161f53646752ec', '至尊宝', '《至尊宝》是《王者荣耀》中的一款热门英雄皮肤，以经典角色形象设计，深受玩家喜爱。', 'article', 'default/content/cover_3bd68fcb-2cde-46fd-9aef-a48371c0a646.jpg', '王者荣耀', 0, 8, 'f', '2026-03-12 14:13:59.431058', '2026-04-13 12:35:18.818818', 'f', NULL, NULL, 'file', '', 0, 'article');
INSERT INTO "public"."content" VALUES ('133e3882b6aa894ede0b58d47d43ec23', '第十届计算机科学与技术田径队', '第十届计算机科学与技术田径队正式成立，展现学子在体育与学术领域的双重风采。', 'article', 'content-covers/cover_05ae01ef-11fe-47be-98ed-c8bc4081baaa.png', '第十届计算机科学与技术田径队', 0, 1, 'f', '2026-05-06 14:25:18.51134', '2026-05-06 14:26:28.762787', 'f', NULL, NULL, 'file', '', 0, 'article');

