INSERT INTO "public"."vector_store" VALUES ('3c8916a2-7d67-4146-a715-b899318ced81', '用户群体，提供可扩展的功能基础，有利于推动个人知识库在学习、科研与实践工作中的应用，对提升个人知识管理能力和信息利用效率具有积极意义。                             二、本课题的基本内容              本课题的主要任务是设计与实现一个基于 Spring Boot3.x + Vue3.x 的个人知识库管理系统，围绕“个人知识资料与多模态内容管理”这一核心目标，完成系统的需求分析、总体设计、详细设计及系统实现与测试。                 课题任务             完成个人知识库系统的需求分析，明确目标用户群体（学生、研究人员、社会工作者等）、业务场景及功能需求，包括多模态内容管理、自然语言检索、用户认证与权限控制等。             设计系统总体架构与技术方案，确定前后端分离架构、数据库选型与数据存储策略、多模态文件的存储与访问方案，以及性能优化策略。             实现个人知识库的核心功能模块，包括：知识内容上传与管理模块、自然语言检索模块、用户与权限管理模块、多端适配界面等。             编写完整的系统开发文档，包括需求说明、UML 类图、数据库设计文档、API 接口文档及使用说明等，为后续维护和二次开发提供依据。             通过功能测试与性能测试，对系统的稳定性、响应速度与用户体验进行评估和优化。                 重点研究内容             多模态个人知识库建模与管理：围绕文本、图片、视频等不同类型数据，研究合理的数据组织结构与元数据设计方案，利用 MySQL 存储结构化数据、MongoDB        存储非       结构化数据，实现对个人知识条目的分类、标注与检索支持。             基于自然语言的智能检索：研究如何结合简单的自然语言处理与检索技术，使用户能够通过自然语言描述查询需求，从个人知识库中获取相关内容，提高检索准确性与易用性。             系统性能与响应优化：以 Redis 作为缓存中间件，对高频访问数据和检索结果进行缓存，加快系统响应速度；同时结合合理的数据库索引与查询优化策略，提升整体系统性能。             多终端适配与交互设计：基于 Vue3.', '{"source": "Invalid source URI: Byte array resource [resource loaded from byte array] cannot be resolved to URL", "document_id": 61, "knowledge_base_id": "d56fde16e3279adeb167b386982b013f"}', '[-0.03023915,0.006919195,0.0020689946,-0.020801352,-0.0076552797,-0.023363722,0.0016850368,0.10656913,-0.022647532,0.101412565,0.095555715,0.016392803,0.0027871744,-0.042462133,-0.0027075976,-0.018923342,0.05996901,-0.047109414,0.014451131,-0.021947257,0.0015527406,-0.03771936,0.041507214,0.01431585,0.0042533753,0.03335856,0.014976338,-0.013130157,0.052743446,-0.003956952,0.0069629624,-0.022838516,0.027692696,-0.011928549,-0.004114116,0.03966103,0.0014363596,0.034695446,-0.0011478941,-0.0056260736,0.0034058832,-0.0056499466,0.009803851,-0.013997544,-0.00067292055,0.019957839,-0.017395468,-0.030127743,-0.01513549,0.050483465,0.014204443,-0.032037582,-0.034313478,0.020244315,-0.028536208,0.009724274,0.0001719603,0.006119449,0.03