INSERT INTO "public"."vector_store" VALUES ('0c3cb5cc-b71f-47e9-bf05-10bb58aaaec6', '+ JavaScript 实现前端界面设计，兼容 PC 端与移动       端访问       需求，注重界面简洁性与操作便捷性，提高用户体验。             安全与权限控制：设计并实现完善的用户认证机制与权限控制模型，保障个人知识数据的安全性、私密性和合       规       性。                 方法与实现途径              本课题将采用“需求分析—系统设计—分模块实现—集成测试—优化完善”的工程化开发流程。后端采用 Spring Boot3.x 框架进行开发，利用其在依赖管理、内嵌服务器、自动配置等方面的优势加快开发效率；前端采用 Vue3.x 框架构建单页应用（SPA），通过 RESTful API 与后端交互。数据层方面，使用 MySQL 存储用户信息、权限信息、结构化知识元数据，使用 MongoDB        存储非       结构化内容描述与部分文档信息，Redis 用于缓存热点数据和检索结果，       MinIO        用于存储上传的文本附件、图片和视频等多模态文件。系统通过 UML 建模工具完成类图、用例图等设计，再依据设计文档进行编码实现。                    进度      规划                              进度安排                    序号                 毕业论文（设计）工作进度                 日期                                  下达任务书、学生提交开题报告               2025.11.09-2025.11.24                                   资料查阅与课题调研，完成国内外相关研究现状分析与可行性研究，初步明确系统功能与技术路线。               2025.11.25-2025.12.10                                   完成系统需求分析与总体设计，包括用例分析、系统架构设计、数据库与存储方案设计等。               2025.12.11-2025.12.25                                   完成后端核心功能开发，包括用户管理、权限控制、多模态内容管理接口、自然语言检索接口等。               2025.12.26-2026.01.20                                   完成前端界面设计与实现，适配 PC 端与移动端，并与后端接口对接，形成可运行的系统原型。               2026.01.21-2026.02.15                                   进行系统联调、功能测试与性能优化，完善 Redis 缓存、文件存储与安全机制。               2026.02.16-2026.    0    3.01                                   整理和完善开发文档，撰写论文（设计）正文，      论文中期检查      。             2026.    0    3.01-2026.04.', '{"source": "Invalid source URI: Byte array resource [resource loaded from byte array] cannot be resolved to URL", "document_id": 61, "knowledge_base_id": "d56fde16e3279adeb167b386982b013f"}', '[-0.071366355,0.001463374,-0.042826425,-0.054831054,-0.061478242,-0.010599127,0.016700651,0.045571286,0.013468001,0.10992667,0.05125943,0.020487236,-0.013236507,-0.000695516,-0.029217875,0.00854875,0.041735094,-0.08962132,0.022008484,-0.021132113,-0.026439944,-0.015882155,0.050135028,0.013310